// Builds theme-bb.css ("Codex (BB colors)") from theme.css ("Codex") by
// swapping each `/* @region name */ ... /* @endregion name */` block for the
// block of the same name in palettes/bb.css. Both themes share everything else.
const REGION = /\/\* @region ([\w-]+) \*\/\n([\s\S]*?)\/\* @endregion \1 \*\//g;

export const GENERATED_HEADER =
  "/* GENERATED by `npm run build:themes` from theme.css and palettes/bb.css.\n" +
  "   Do not edit; change those files and rebuild. */\n\n";

export function regions(css) {
  const found = new Map();
  for (const [, name, body] of css.matchAll(REGION)) {
    if (found.has(name)) throw new Error(`Region "${name}" appears twice`);
    found.set(name, body);
  }
  return found;
}

export function buildBbTheme(themeCss, paletteCss) {
  const base = regions(themeCss);
  const replacements = regions(paletteCss);
  const missing = [...base.keys()].filter((name) => !replacements.has(name));
  const extra = [...replacements.keys()].filter((name) => !base.has(name));
  if (missing.length) throw new Error(`palettes/bb.css is missing regions: ${missing.join(", ")}`);
  if (extra.length) throw new Error(`palettes/bb.css has regions theme.css lacks: ${extra.join(", ")}`);
  return GENERATED_HEADER + themeCss.replace(REGION, (_match, name) => replacements.get(name).trimEnd());
}
